// Demo: Side-Channel Resistant KEMs — KAT-style determinism check
function kem(seed){var h=0;var s='kat'+seed;for(var i=0;i<s.length;i++){h=(h*31+s.charCodeAt(i))>>>0;}return h.toString(16);}
var a=kem(6),b=kem(6);
console.log('technique: Side-Channel Resistant KEMs');console.log('run1: '+a+', run2: '+b);
console.log(a===b?'deterministic — KAT passes':'NONDETERMINISM — investigate');

